toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #0A0B0E;
  font-family: "Space Grotesk, sans-serif";
}

>cyan = #00E5FF;
>pureWhite = #FFFFFF;
>dimGray = #8A92A6;
>deepRing = #161F30;

circle #outerBackdrop {
  at: center of canvas;
  size: 320px;
  fill: none;
  stroke: >deepRing;
  stroke-width: 2px;
}

circle #outerRing {
  at: center of canvas;
  size: 240px;
  fill: none;
  stroke: >cyan;
  stroke-width: 4px;
}

circle #innerCore {
  at: center of canvas;
  size: 110px;
  fill: >cyan;
}

rect #cutoutVertical {
  at: center of canvas;
  size: 24px 280px;
  fill: #0A0B0E;
}

text #brandTitle {
  at: below #outerBackdrop offset 48px;
  content: "A E R O";
  font-size: 28px;
  font-weight: 700;
  color: >pureWhite;
}

text #brandSubtitle {
  at: below #brandTitle offset 12px;
  content: "KINETIC PRECISION LABS";
  font-size: 12px;
  font-weight: 500;
  color: >dimGray;
}
